import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Persistence and Crash Consistency","description":"","frontmatter":{"title":"Persistence and Crash Consistency"},"headers":[],"relativePath":"guide/persistence.md","filePath":"guide/persistence.md","lastUpdated":1793266312000}`),a={name:`guide/persistence.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_7-persistence-and-crash-consistency" tabindex="-1">7. Persistence and Crash Consistency <a class="header-anchor" href="#_7-persistence-and-crash-consistency" aria-label="Permalink to “7. Persistence and Crash Consistency”">​</a></h1><h2 id="_7-1-database" tabindex="-1">7.1 Database <a class="header-anchor" href="#_7-1-database" aria-label="Permalink to “7.1 Database”">​</a></h2><p>The first version uses SQLite.</p><p>Enabling WAL is recommended, with an appropriate <code>synchronous</code> strategy chosen according to reliability requirements. Do not assume WAL automatically guarantees every record is durable, and there is no need to unconditionally fsync after every log write.</p><p>For critical recovery operations, transaction boundaries should be explicit.</p><h2 id="_7-2-core-tables" tabindex="-1">7.2 Core tables <a class="header-anchor" href="#_7-2-core-tables" aria-label="Permalink to “7.2 Core tables”">​</a></h2><p>At least the following are recommended:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>resources</span></span>
<span class="line"><span>resource_dependencies</span></span>
<span class="line"><span>resource_health</span></span>
<span class="line"><span>incidents</span></span>
<span class="line"><span>recovery_runs</span></span>
<span class="line"><span>recovery_steps</span></span>
<span class="line"><span>probe_results</span></span>
<span class="line"><span>diagnoses</span></span>
<span class="line"><span>action_attempts</span></span>
<span class="line"><span>verification_results</span></span>
<span class="line"><span>audit_events</span></span>
<span class="line"><span>notification_queue</span></span>
<span class="line"><span>notification_attempts</span></span>
<span class="line"><span>plugin_registry</span></span>
<span class="line"><span>configuration_versions</span></span></code></pre></div><p>Where:</p><ul><li><code>resources</code> stores resource definitions.</li><li><code>resource_dependencies</code> stores dependency relationships.</li><li><code>resource_health</code> stores the current health snapshot.</li><li><code>incidents</code> stores fault lifecycles.</li><li><code>recovery_runs</code> stores recovery tasks.</li><li><code>recovery_steps</code> stores step order and status.</li><li><code>probe_results</code> stores probe evidence.</li><li><code>diagnoses</code> stores diagnosis results.</li><li><code>action_attempts</code> stores every action attempt.</li><li><code>verification_results</code> stores verification results.</li><li><code>audit_events</code> stores event auditing.</li><li><code>notification_queue</code> stores pending notifications.</li><li><code>notification_attempts</code> stores delivery history.</li><li><code>plugin_registry</code> stores loaded plugins and their capabilities.</li><li><code>configuration_versions</code> stores configuration versions or change summaries.</li></ul><h2 id="_7-3-persistence-order-for-high-risk-actions" tabindex="-1">7.3 Persistence order for high-risk actions <a class="header-anchor" href="#_7-3-persistence-order-for-high-risk-actions" aria-label="Permalink to “7.3 Persistence order for high-risk actions”">​</a></h2><p>Before executing a high-risk action:</p><ol><li>Validate the resource and dependency conditions.</li><li>Validate action permissions.</li><li>Validate budget and mutexes.</li><li>Create the ActionAttempt.</li><li>Mark the status as <code>Executing</code>.</li><li>Execute the external action only after the transaction commits successfully.</li><li>Record the action&#39;s return result.</li><li>Re-verify resource health.</li><li>Update the RecoveryRun status.</li></ol><p>If Custos crashes during step 6, then after recovery it must recognize that the execution outcome may be unknown.</p><p>&quot;Database status written as Executing&quot; must not be mistaken for &quot;the external action definitely ran&quot;, and &quot;the external action returned 0&quot; must not be mistaken for &quot;the service definitely recovered&quot;.</p><h2 id="_7-4-data-retention" tabindex="-1">7.4 Data retention <a class="header-anchor" href="#_7-4-data-retention" aria-label="Permalink to “7.4 Data retention”">​</a></h2><p>Configuration:</p><ul><li>Audit record retention period.</li><li>Probe detail retention period.</li><li>Recovery task retention period.</li><li>Notification delivery record retention period.</li><li>Database size limit.</li></ul><p>By default, do not delete Incidents, RecoveryRuns that are still active, or notifications not yet delivered.</p><p>Log compaction or cleanup must be decoupled from active task state.</p><hr>`,21)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};